import{_ as r,a0 as l,w as p,s as u,ao as s,I as d,x as n,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"LinuxCon大会：Google Android是开源产品 | LCTT x X-CMD","titleTemplate":false,"description":"LinuxCon大会：Google Android是开源产品 | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LinuxCon大会：Google Android是开源产品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LinuxCon大会：Google Android是开源产品 | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/Google Android Is Open Source- LinuxCon","title":"LinuxCon大会：Google Android是开源产品","tag":"201309","desc":""},"relativePath":"201309/Google Android Is Open Source- LinuxCon.md","filePath":"[post].md"}'),a={name:"201309/Google Android Is Open Source- LinuxCon.md"};function g(x,o,m,A,C,L){const i=l("Link");return p(),u("div",null,[o[19]||(o[19]=s('<h1 id="linuxcon大会-google-android是开源产品" tabindex="-1">LinuxCon大会：Google Android是开源产品 <a class="header-anchor" href="#linuxcon大会-google-android是开源产品" aria-label="Permalink to “LinuxCon大会：Google Android是开源产品”">​</a></h1><p><em><strong>Google的首席开源执行官在LinuxCon大会上说明了为何Android是开源的以及为何开源是Android成功的关键因素</strong></em></p><p>9月16日，新奥尔良，LinuxCon大会，负责开源的Google董事Chris DiBona在主题演讲中发布了一条关键信息：Android是一款开源产品。</p><p>Google在开源社区中能够确保不犯错并一直遵守开源授权的要求，DiBona在这其中发挥了关键作用。DiBona在演讲中介绍，早在2005年，从Android发展战略刚刚开始的时候，其平台的核心基础就是要始终保持开源。</p><p>2005年，Google面临的困难挑战是如何将它的搜索引擎植入手机。当时，手持设备的市场还很封闭，Google要想进入到手机市场，必须经历一个步履维艰的过程。Google要想确保它的搜索引擎能够轻易部署到每一部手机，在某种程度上，Android就成为了一种尝试。</p><p>DiBona说，“我们希望人们在使用手机的时候，能拥有和电脑桌面一样的体验，但当时在开源领域并没有这样的产品”。</p><p>Google希望的是，Android只为用户提供手机所必需的基本功能，DiBona说，Google并不愿因为在手机上搞竞价排名或定制服务而和运营商们无休止地讨价还价。</p><p>DiBona还说，“手机运营商再也不能靠捆绑销售来竞争了，手机市场必须有一个自由环境。”</p><p>DiBona介绍，Android已经成为Google极其成功的一项成就，而且它每年都在变得更好。他还补充说，目前，新的Android设备每天的激活量已经达到130万台。</p><p>###Linux</p>',10)),d("p",null,[o[1]||(o[1]=n("从Android利用Linux作为自身平台重要的组成部分开始，它们之间就注定结下不解之缘。2010年，Google的Android代码被从Linux核心中",-1)),e(i,{href:"http://www.linuxplanet.com/linuxplanet/reports/7150/1/"},{default:t(()=>[...o[0]||(o[0]=[n("剔除",-1)])]),_:1}),o[2]||(o[2]=n("。",-1))]),d("p",null,[o[5]||(o[5]=n("直到2012年三月",-1)),e(i,{href:"http://www.datamation.com/open-source/linux-3.3-boosts-linux-mobility.html"},{default:t(()=>[...o[3]||(o[3]=[n("Linux内核3.3",-1)])]),_:1}),o[6]||(o[6]=n("发布，Android才最终回到Linux核心代码中。DiBona评论说，他始终认为Linux和Android在一起是个好主意。关于它俩是否应该在一起的争论，这是个很技术的技术问题，涉及到一种叫做",-1)),e(i,{href:"http://developer.android.com/reference/android/os/PowerManager.WakeLock.html"},{default:t(()=>[...o[4]||(o[4]=[n("WakeLock",-1)])]),_:1}),o[7]||(o[7]=n("的省电机制。",-1))]),o[20]||(o[20]=d("p",null,"争论先放一边，DiBona说，有些人质疑Android是否真的开源，简单一句话就可以证明，屡试不爽。不需要Google的参与甚至许可，任何人都可以在任何设备上安装Android。而正是因为Google在开源许可的授权下开发了Android，以上这一切才能成为事实。",-1)),o[21]||(o[21]=d("p",null,"DiBona最后总结时强调，是开源造就了Google的Android，开源作为Android的核心观念，早已根深蒂固。",-1)),d("p",null,[o[9]||(o[9]=n("via: ",-1)),e(i,{href:"http://www.eweek.com/mobile/google-android-is-open-source-linuxcon.html"},{default:t(()=>[...o[8]||(o[8]=[n("http://www.eweek.com/mobile/google-android-is-open-source-linuxcon.html",-1)])]),_:1})]),d("p",null,[o[12]||(o[12]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...o[10]||(o[10]=[n("LCTT",-1)])]),_:1}),o[13]||(o[13]=n(" 原创翻译，",-1)),e(i,{href:"http://linux.cn/portal.php"},{default:t(()=>[...o[11]||(o[11]=[n("Linux中国",-1)])]),_:1}),o[14]||(o[14]=n(" 荣誉推出",-1))]),d("p",null,[o[17]||(o[17]=n("译者：",-1)),e(i,{href:"http://linux.cn/space/14801"},{default:t(()=>[...o[15]||(o[15]=[n("Mr小眼儿",-1)])]),_:1}),o[18]||(o[18]=n(" 校对：",-1)),e(i,{href:"http://linux.cn/space/14763"},{default:t(()=>[...o[16]||(o[16]=[n("Caroline",-1)])]),_:1})])])}const w=r(a,[["render",g]]);export{T as __pageData,w as default};
